<script lang="ts">
  import { page } from '$app/stores';
  import { goto } from '$app/navigation';
  import NotificationBell from '$lib/components/NotificationBell.svelte';
  import NotificationToaster from '$lib/components/NotificationToaster.svelte';
  import { roleLabels, roleRoutes, type Role } from '$lib/auth';

  type Icon = 'home'|'students'|'teachers'|'class'|'finance'|'receipt'|'calendar'|'message'|'settings'|'report'|'more';
  type NavItem = { label:string; href:string; icon:Icon };
  type NavGroup = { label:string; items:NavItem[]; defaultOpen?:boolean };
  const { title, subtitle='', headerActions, rightRail, role='school_admin', roles=null, user={name:'eShule Admin',email:'admin@eshule.app'}, brandName='eShule', logoUrl='', canAccessCommittee=false, children } = $props<{title:string;subtitle?:string;headerActions?:import('svelte').Snippet;rightRail?:import('svelte').Snippet;role?:string;roles?:Role[]|null;user?:{name?:string;email?:string};brandName?:string;logoUrl?:string;canAccessCommittee?:boolean;children?:import('svelte').Snippet}>();
  const icons:Record<Icon,string>={home:'M3 12l9-9 9 9M5 10v10h14V10M9 20v-6h6v6',students:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',teachers:'M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',class:'M4 5h16v14H4zM8 9h8M8 13h5',finance:'M3 10h18M5 6h14a2 2 0 0 1 2 2v10H3V8a2 2 0 0 1 2-2',receipt:'M6 2h9l3 3v17l-3-2-3 2-3-2-3 2V4a2 2 0 0 1 2-2',calendar:'M7 3v4M17 3v4M4 9h16M5 5h14a1 1 0 0 1 1 1v13H4V6a1 1 0 0 1 1-1Z',message:'M4 5h16v11H8l-4 4V5Z',settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7',report:'M5 20V10M12 20V4M19 20v-7',more:'M6 12h.01M12 12h.01M18 12h.01'};
  const roleNav:Record<string,NavGroup[]>={
    school_admin:[{label:'Today',defaultOpen:true,items:[{label:'Dashboard',href:'/admin',icon:'home'}]},{label:'Students',defaultOpen:true,items:[{label:'Students',href:'/admin/students',icon:'students'},{label:'Admissions',href:'/admin/sis/admissions',icon:'students'},{label:'Enrollment',href:'/admin/sis/enrollment',icon:'class'},{label:'Graduation / Exit',href:'/admin/sis/graduation',icon:'students'}]},{label:'ReClass',defaultOpen:true,items:[{label:'ReClass',href:'/admin/reclass',icon:'home'},{label:'Scheduling',href:'/admin/scheduling',icon:'calendar'},{label:'Attendance',href:'/admin/attendance',icon:'calendar'}]},{label:'Operations',items:[{label:'Calendar',href:'/admin/calendar',icon:'calendar'},{label:'Lessons',href:'/admin/lessons',icon:'class'},{label:'Reminders',href:'/admin/reminders',icon:'message'}]},{label:'Finance',items:[{label:'Finance',href:'/admin/finance',icon:'finance'},{label:'Receipts',href:'/admin/finance/receipts',icon:'receipt'},{label:'Payroll',href:'/admin/finance/payroll',icon:'receipt'}]},{label:'Administration',items:[{label:'Parents',href:'/admin/parents',icon:'students'},{label:'Teachers',href:'/admin/teachers',icon:'teachers'},{label:'Reports',href:'/admin/analytics',icon:'report'},{label:'Settings',href:'/admin/settings',icon:'settings'}]}],
    teacher:[{label:'Today',defaultOpen:true,items:[{label:'Dashboard',href:'/teacher',icon:'home'},{label:'Timetable',href:'/teacher/timetable',icon:'calendar'},{label:'Lessons',href:'/teacher/lessons',icon:'class'}]},...(canAccessCommittee?[{label:'Responsibilities',defaultOpen:true,items:[{label:'Committee',href:'/teacher/committee',icon:'teachers'}]}] as NavGroup[]:[]),{label:'Account',items:[{label:'Profile',href:'/account',icon:'settings'}]}],
    parent:[{label:'My child',defaultOpen:true,items:[{label:'Home',href:'/parent',icon:'home'},{label:'Child profile',href:'/parent/child',icon:'students'},{label:'Timetable',href:'/parent/timetable',icon:'calendar'},{label:'Payments',href:'/parent/payments',icon:'receipt'}]}],
    principal:[{label:'Today',defaultOpen:true,items:[{label:'Overview',href:'/principal',icon:'home'},{label:'Reports',href:'/principal/reports',icon:'report'}]}],
    bursar:[{label:'Finance',defaultOpen:true,items:[{label:'Workspace',href:'/bursar',icon:'home'},{label:'Receipts',href:'/bursar/receipts',icon:'receipt'}]}],
    super_admin:[{label:'Platform',defaultOpen:true,items:[{label:'Dashboard',href:'/super-admin',icon:'home'},{label:'Tenants',href:'/super-admin/tenants',icon:'students'},{label:'Modules',href:'/super-admin/modules',icon:'class'}]}]
  };
  const nav=$derived(roleNav[role]??roleNav.school_admin); let openGroups=$state<Record<string,boolean>>({}); let moreOpen=$state(false); const userName=$derived(user?.name??'eShule Admin');
  $effect(()=>{const next:Record<string,boolean>={};for(const group of nav)next[group.label]=group.defaultOpen??group.items.some(i=>active(i.href));openGroups=next;});
  function active(href:string){return ['/admin','/teacher','/parent','/principal','/bursar','/super-admin'].includes(href)?$page.url.pathname===href:$page.url.pathname.startsWith(href)}
  async function switchRole(next:Role){await fetch('/api/role/switch',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({role:next})});await goto(roleRoutes[next]);}
</script>
<div class="min-h-screen bg-slate-50 text-slate-900"><div class="flex min-h-screen"><aside class="hidden w-64 shrink-0 flex-col border-r bg-white md:flex"><div class="flex h-16 items-center gap-3 border-b px-4">{#if logoUrl}<img src={logoUrl} alt={brandName} class="h-9 w-9 rounded-lg object-contain"/>{:else}<div class="flex h-9 w-9 items-center justify-center rounded-xl bg-primary font-bold text-white">{brandName.slice(0,1)}</div>{/if}<div><p class="text-sm font-semibold">{brandName}</p><p class="text-[11px] text-slate-500">{roleLabels[role as Role]??role}</p></div></div><nav class="flex-1 overflow-y-auto p-3" aria-label="Main navigation">{#each nav as group}<section class="mb-4"><button type="button" class="flex w-full justify-between px-2 py-1 text-[10px] font-semibold uppercase tracking-wider text-slate-400" onclick={()=>openGroups[group.label]=!openGroups[group.label]} aria-expanded={openGroups[group.label]}>{group.label}</button>{#if openGroups[group.label]}<div class="mt-1 space-y-0.5">{#each group.items as item}<a href={item.href} aria-current={active(item.href)?'page':undefined} class="flex min-h-10 items-center gap-3 rounded-lg px-3 text-sm {active(item.href)?'bg-primary/10 text-primary':'text-slate-600 hover:bg-slate-50'}"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d={icons[item.icon]}/></svg>{item.label}</a>{/each}</div>{/if}</section>{/each}</nav>{#if roles&&roles.length>1}<div class="border-t p-3">{#each roles as r}{#if r!==role}<button type="button" class="mr-1 rounded border px-2 py-1 text-xs" onclick={()=>switchRole(r)}>{roleLabels[r]}</button>{/if}{/each}</div>{/if}<div class="border-t p-3"><p class="truncate text-xs font-semibold">{userName}</p></div></aside><div class="flex min-w-0 flex-1 flex-col"><header class="sticky top-0 z-30 flex min-h-16 items-center gap-3 border-b bg-white/95 px-4 sm:px-6"><div class="min-w-0 flex-1"><p class="text-[11px] text-slate-400">{roleLabels[role as Role]??role}</p><h1 class="truncate text-base font-semibold">{title}</h1>{#if subtitle}<p class="hidden truncate text-xs text-slate-500 sm:block">{subtitle}</p>{/if}</div>{#if headerActions}{@render headerActions()}{/if}<NotificationBell tenantId={$page.data.tenantId}/></header><div class="flex min-h-0 flex-1"><main id="main-content" class="min-w-0 flex-1 px-4 py-5 pb-24 sm:px-6 lg:px-8 lg:py-8"><div class="mx-auto w-full max-w-7xl space-y-6">{@render children?.()}</div></main>{#if rightRail}<aside class="hidden w-72 border-l bg-white p-5 xl:block">{@render rightRail()}</aside>{/if}</div></div></div><NotificationToaster/><nav class="fixed inset-x-0 bottom-0 z-40 border-t bg-white md:hidden"><div class="flex">{#each nav.flatMap(g=>g.items).slice(0,4) as item}<a href={item.href} class="flex min-h-12 flex-1 flex-col items-center justify-center text-[10px] {active(item.href)?'text-primary':'text-slate-500'}"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d={icons[item.icon]}/></svg><span>{item.label}</span></a>{/each}{#if nav.flatMap(g=>g.items).length>4}<button type="button" class="flex min-h-12 flex-1 flex-col items-center justify-center text-[10px] text-slate-500" onclick={()=>moreOpen=!moreOpen}><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d={icons.more}/></svg><span>More</span></button>{/if}</div></nav>{#if moreOpen}<section class="fixed inset-x-0 bottom-0 z-50 max-h-[75vh] overflow-y-auto rounded-t-3xl border bg-white p-5 shadow-2xl md:hidden"><div class="mb-4 flex justify-between"><b>More</b><button type="button" onclick={()=>moreOpen=false}>Close</button></div>{#each nav as group}<p class="mb-2 text-xs font-semibold uppercase text-slate-400">{group.label}</p>{#each group.items as item}<a href={item.href} onclick={()=>moreOpen=false} class="block rounded-lg px-3 py-2 text-sm hover:bg-slate-50">{item.label}</a>{/each}{/each}</section>{/if}</div>
